/* ---- nav: hide on scroll down, show on scroll up (matches home) ---- */
(function(){
  var nav = document.querySelector('.nav');
  if (!nav) return;
  var last = window.pageYOffset || 0, ticking = false;
  function onScroll(){
    ticking = false;
    var y = window.pageYOffset || document.documentElement.scrollTop || 0;
    if (nav.classList.contains('open')){ document.body.classList.remove('nav-up'); last = y; return; }
    if (y > last && y > 140){ document.body.classList.add('nav-up'); }
    else { document.body.classList.remove('nav-up'); }
    last = y < 0 ? 0 : y;
  }
  window.addEventListener('scroll', function(){ if (!ticking){ ticking = true; requestAnimationFrame(onScroll); } }, { passive:true });
})();

/* module tiles: force muted autoplay, play only when in view (perf + reliability) */
(function(){
  var vids = document.querySelectorAll('.module-vid');
  if (!vids.length) return;
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  vids.forEach(function(v){ v.muted = true; v.setAttribute('muted',''); });
  if ('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(es){
      es.forEach(function(e){ if (e.isIntersecting){ var p=e.target.play(); if(p&&p.catch)p.catch(function(){}); } else { e.target.pause(); } });
    }, { threshold: 0.12 });
    vids.forEach(function(v){ io.observe(v); });
  } else { vids.forEach(function(v){ var p=v.play(); if(p&&p.catch)p.catch(function(){}); }); }
})();

/* curriculum scroll-spy: highlight the active module in the sticky list */
(function(){
  var mods = document.querySelectorAll('.curr-mod');
  var items = document.querySelectorAll('.curr-nav-item');
  if(!mods.length || !('IntersectionObserver' in window)) return;
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(e.isIntersecting){
        var id = e.target.id;
        items.forEach(function(n){ n.classList.toggle('is-active', n.getAttribute('data-target')===id); });
      }
    });
  }, { rootMargin:'-45% 0px -50% 0px', threshold:0 });
  mods.forEach(function(m){ io.observe(m); });
})();
